import torch
import torch.nn as nn

# PTX source for sigmoid on fp16 tensors (A100, sm_80)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry sigmoid_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N
)
{
    // --------------------
    // registers
    // --------------------
    .reg .pred   %p1, %p2;
    .reg .b64    %rd1, %rd2, %rd3, %rd4, %rd5;
    .reg .b32    %rN, %r_tid, %r_total, %r_tmp;
    .reg .f16    %fh;
    .reg .f32    %f32, %neg, %scaled, %exp, %denom, %out;

    // --------------------
    // load kernel parameters
    // --------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %rN,  [N];

    // --------------------
    // compute thread id (tid) and total threads (total)
    // --------------------
    mov.u32         %r_tmp, %ctaid.x;          // blockIdx.x
    mul.lo.u32      %r_tmp, %r_tmp, %ntid.x;   // blockIdx.x * blockDim.x
    add.u32         %r_tid, %r_tmp, %tid.x;    // tid = blockIdx.x*blockDim.x + threadIdx.x

    mul.lo.u32      %r_total, %nctaid.x, %ntid.x; // total = gridDim.x * blockDim.x

    // --------------------
    // early exit if tid >= N
    // --------------------
    setp.ge.u32     %p1, %r_tid, %rN;
    @%p1            bra DONE;

LOOP:
    // ---- load half (fp16) element ----
    mul.wide.u32    %rd3, %r_tid, 2;           // offset in bytes (2 bytes per fp16)
    add.u64         %rd4, %rd1, %rd3;          // address of input element
    ld.global.nc.f16 %fh, [%rd4];

    // ---- convert to fp32 ----
    cvt.rn.f32.f16  %f32, %fh;

    // ---- sigmoid = 1 / (1 + exp(-x)) ----
    // -x
    neg.f32         %neg, %f32;
    // scale by 1/ln2 (≈1.4426950408889634) to use ex2.approx
    mov.f32         %scaled, 1.4426950408889634;
    mul.f32         %scaled, %neg, %scaled;
    // exp approximation: 2^{scaled}
    ex2.approx.f32  %exp, %scaled;
    // denominator = 1 + exp
    add.f32         %denom, %exp, 1.0;
    // output = 1 / denominator (approx reciprocal)
    rcp.approx.f32  %out, %denom;

    // ---- convert back to fp16 and store ----
    cvt.rn.f16.f32  %fh, %out;
    add.u64         %rd5, %rd2, %rd3;          // address of output element
    st.global.f16   [%rd5], %fh;

    // ---- advance index by total threads ----
    add.u32         %r_tid, %r_tid, %r_total;
    setp.lt.u32     %p2, %r_tid, %rN;
    @%p2            bra LOOP;

DONE:
    ret;
}
'''

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that runs a custom PTX
    sigmoid kernel on fp16 tensors (A100, sm_80).
    """
    def __init__(self):
        super().__init__()
        # Load the PTX module using the harness API
        self._module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply sigmoid using the custom PTX kernel.

        Args:
            x (torch.Tensor): fp16 tensor of any shape (must be contiguous).

        Returns:
            torch.Tensor: Tensor with sigmoid applied, same shape and dtype.
        """
        if not x.is_contiguous():
            x = x.contiguous()
        assert x.dtype == torch.float16, "ModelNew only supports float16 inputs"
        out = torch.empty_like(x)

        total_elements = x.numel()
        # Choose a reasonable block size; 256 is a common choice for A100
        block_dim = 256
        grid_dim = ( (total_elements + block_dim - 1) // block_dim, )

        # Prepare argument list for the PTX launch
        args = [
            x.data_ptr(),
            out.data_ptr(),
            total_elements
        ]

        # Launch kernel: kernel name is "sigmoid_kernel"
        ptx_launch(self._module, "sigmoid_kernel", grid_dim, (block_dim,), args)

        return out
